// Built-in radio stations: genre views over the recorded library, so a
// listener can pick the music independently of the café they sit in.
// musicManifest.js is regenerated by tools/gen-manifest.mjs; genre tags live
// here so regeneration never loses them. Untagged tracks still play in
// "Café pick" (their own café) and "Shuffle all".
import { MUSIC_MANIFEST } from './musicManifest.js';

export const MUSIC_STATIONS = Object.freeze([
  Object.freeze({ id: 'cafe', label: 'Café pick', description: 'Each café plays its own records' }),
  Object.freeze({ id: 'lofi', label: 'Lo-fi', description: 'Dusty beats and warm tape' }),
  Object.freeze({ id: 'jazz', label: 'Jazz', description: 'Brushes, upright bass and keys' }),
  Object.freeze({ id: 'bossa', label: 'Bossa & samba', description: 'Nylon strings and light percussion' }),
  Object.freeze({ id: 'piano', label: 'Piano & soul', description: 'Slow keys and soft grooves' }),
  Object.freeze({ id: 'shuffle', label: 'Shuffle all', description: 'Every record in the house' }),
]);
export const MUSIC_STATION_IDS = Object.freeze(MUSIC_STATIONS.map((s) => s.id));
export const DEFAULT_MUSIC_STATION = 'cafe';

export const TRACK_GENRES = Object.freeze({
  'airport-lounge': ['bossa', 'piano'],
  everything: ['lofi'],
  'smooth-lovin': ['piano', 'jazz'],
  'warm-fuzz': ['lofi'],
  wholesome: ['piano'],
  'backed-vibes-clean': ['jazz', 'lofi'],
  'beyond-piano': ['piano'],
  'i-knew-a-guy': ['jazz'],
  'jazz-one': ['jazz', 'lofi'],
  'jazz-two': ['jazz', 'lofi'],
  'lobby-time': ['jazz', 'bossa'],
  'bossa-antigua': ['bossa'],
  'busted-jazz': ['jazz', 'lofi'],
  'cellar-door': ['lofi'],
  'george-street-shuffle': ['jazz'],
  'samba-isobel': ['bossa'],
});

// The Garden Terrace has no playlist of its own: an open-air mix.
const VENUE_MIXES = Object.freeze({
  terrace: ['airport-lounge', 'bossa-antigua', 'samba-isobel', 'wholesome', 'smooth-lovin', 'warm-fuzz'],
});

export function isMusicStation(id) {
  return MUSIC_STATION_IDS.includes(id);
}

function allTracks(manifest) {
  const seen = new Map();
  for (const list of Object.values(manifest)) for (const track of list) if (!seen.has(track.id)) seen.set(track.id, track);
  return [...seen.values()];
}

// Tracks for a station in a given café. Never empty while the library has
// any track: an unknown café or genre falls back to the whole library.
export function stationTracks(stationId, themeId, manifest = MUSIC_MANIFEST) {
  const library = allTracks(manifest);
  let pool;
  if (stationId === 'shuffle') pool = library;
  else if (!isMusicStation(stationId) || stationId === 'cafe') {
    const mix = VENUE_MIXES[themeId];
    pool = manifest[themeId] ?? (mix ? library.filter((t) => mix.includes(t.id)) : null) ?? manifest.goldenhour ?? [];
  } else {
    pool = library.filter((t) => TRACK_GENRES[t.id]?.includes(stationId));
  }
  return pool.length ? pool : library;
}
